return [
  { json: { marca: 'aristocrata', url: 'https://www.reclameaqui.com.br/empresa/o-aristocrata-1751961/' } },
  { json: { marca: 'fishermans',  url: 'https://www.reclameaqui.com.br/empresa/artigos-de-pesca-fishermans/' } },
];

// Le as metatags meta-reclameaqui:* e alguns numeros do corpo. Se a pagina veio bloqueada
// (403/captcha), nao grava nada e lanca erro -- ausencia nunca vira zero.
const marca = $('Marcas').item.json.marca;
const html = String($input.item.json.data || $input.item.json.body || $input.item.json || '');
if (!/reclameaqui:/.test(html)) throw new Error(`RA ${marca}: pagina sem metatags (bloqueio anti-bot? ${html.length} bytes)`);
const meta = (nome) => { const m = html.match(new RegExp('<meta[^>]+reclameaqui:' + nome + '[^>]+content="([^"]*)"', 'i')) || html.match(new RegExp('content="([^"]*)"[^>]+reclameaqui:' + nome, 'i')); return m ? m[1] : null; };
const num = (s) => s === null || s === '' ? null : Number(String(s).replace(',', '.'));
const corpo = (re) => { const m = html.match(re); return m ? num(m[1]) : null; };
return { json: {
  marca, nota: num(meta('reputation-score')), resposta_pct: num(meta('response-rate')), solucao_pct: num(meta('solved-rate')),
  voltaria_pct: num(meta('deal-again-rate')), reclamacoes: num(meta('total-complaints')), avaliacoes: num(meta('total-ratings')),
  nota_consumidor: corpo(/nota do consumidor[^0-9]{0,80}([0-9]+[.,]?[0-9]*)/i),
  aguardando: corpo(/([0-9.]+)\s*(?:reclama[cç][oõ]es?\s*)?(?:aguardando|n[aã]o respondid)/i),
  tempo_resposta_dias: corpo(/tempo m[eé]dio de resposta[^0-9]{0,40}([0-9]+)/i),
  status_ra: meta('status') || null,
} };

const q = (v) => v === null || v === undefined || Number.isNaN(v) ? 'NULL' : typeof v === 'number' ? String(v) : "'" + String(v).replace(/'/g, "''") + "'";
const vals = $input.all().map((i) => { const r = i.json; return '(' + [r.marca, r.nota, r.resposta_pct, r.solucao_pct, r.voltaria_pct, r.nota_consumidor, r.reclamacoes, r.avaliacoes, r.aguardando, r.tempo_resposta_dias, r.status_ra].map(q).join(',') + ",'metatag')"; });
return [{ json: { sql: `INSERT INTO cx_ra_dia (marca, nota, resposta_pct, solucao_pct, voltaria_pct, nota_consumidor, reclamacoes, avaliacoes, aguardando, tempo_resposta_dias, status_ra, fonte, dia)
  SELECT v.*, (now() AT TIME ZONE 'America/Sao_Paulo')::date FROM (VALUES ${vals.join(',')}) AS v(marca, nota, resposta_pct, solucao_pct, voltaria_pct, nota_consumidor, reclamacoes, avaliacoes, aguardando, tempo_resposta_dias, status_ra, fonte)
  ON CONFLICT (marca, dia) DO UPDATE SET nota=EXCLUDED.nota, resposta_pct=EXCLUDED.resposta_pct, solucao_pct=EXCLUDED.solucao_pct, voltaria_pct=EXCLUDED.voltaria_pct,
    nota_consumidor=EXCLUDED.nota_consumidor, reclamacoes=EXCLUDED.reclamacoes, avaliacoes=EXCLUDED.avaliacoes, aguardando=EXCLUDED.aguardando,
    tempo_resposta_dias=EXCLUDED.tempo_resposta_dias, status_ra=EXCLUDED.status_ra, fonte=EXCLUDED.fonte, coletado_em=now()` } }];
